  static String lookup(String languageCode, String key, [String? countryCode]) {
    // 1. Try full languageCode_countryCode (e.g. en_GB, zh_CN, zh_TW)
    if (countryCode != null && countryCode.isNotEmpty) {
      final compositeKey = '${languageCode}_$countryCode';
      final langMap = translations[compositeKey];
      if (langMap != null && langMap.containsKey(key)) {
        return langMap[key]!;
      }
    }

    // 2. Try languageCode
    final langMap = translations[languageCode];
    if (langMap != null && langMap.containsKey(key)) {
      return langMap[key]!;
    }

    // 3. Fallback to English (United States)
    final enMap = translations['en'];
    if (enMap != null && enMap.containsKey(key)) {
      return enMap[key]!;
    }

    return key;
  }
}
